'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { resolve } = require('./index');
const { parse, compare, satisfies, compileRange } = require('./semver');

test('candidate order compares every numeric component', () => {
  const registry = {
    major: { '9.99.99': {}, '10.0.0': {} },
    minor: { '1.9.99': {}, '1.10.0': {} },
    patch: { '1.0.9': {}, '1.0.10': {} },
  };
  assert.deepEqual(resolve(registry, { major: '*', minor: '*', patch: '*' }), {
    major: '10.0.0', minor: '1.10.0', patch: '1.0.10',
  });
});

test('discovery collects all constraints before queued choices', () => {
  const registry = {
    a: { '2.0.0': { x: '*' }, '1.0.0': {} },
    b: { '2.0.0': { x: '1.0.0' }, '1.0.0': { x: '2.0.0' } },
    x: { '2.0.0': {}, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*', x: '*', b: '*' }), {
    a: '2.0.0', x: '2.0.0', b: '1.0.0',
  });
  assert.deepEqual(resolve(registry, { a: '*', b: '*' }), {
    a: '2.0.0', b: '2.0.0', x: '1.0.0',
  });
});

test('a discovered conflict retries the latest choice and removes partial dependencies', () => {
  const registry = {
    a: { '2.0.0': {}, '1.0.0': {} },
    b: { '2.0.0': { discarded: '*', a: '1.0.0' }, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*', b: '*' }), { a: '2.0.0', b: '1.0.0' });
});

test('rollback removes failed branch constraints, queued names and selections', () => {
  const registry = {
    a: { '2.0.0': { x: '1.0.0', missing: '*' }, '1.0.0': { x: '2.0.0' } },
    x: { '2.0.0': {}, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*', x: '*' }), { a: '1.0.0', x: '2.0.0' });
});

test('rollback preserves constraints from earlier choices', () => {
  const registry = {
    a: { '1.0.0': { x: '<2.0.0' } },
    b: { '2.0.0': { x: '2.0.0' }, '1.0.0': { x: '*' } },
    x: { '2.0.0': {}, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*', b: '*' }), {
    a: '1.0.0', b: '1.0.0', x: '1.0.0',
  });
});

test('cycles expand each selected package once and still enforce incoming constraints', () => {
  const registry = {
    a: { '2.0.0': { b: '*' }, '1.0.0': { a: '*', b: '*' } },
    b: { '1.0.0': { a: '1.0.0' } },
  };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
  assert.equal(resolve(registry, { a: '2.0.0' }), null);
});

test('long chains resolve without a call-stack or iteration limit', () => {
  const registry = {};
  const expected = {};
  for (let i = 0; i < 15000; i += 1) {
    registry[`p${i}`] = { '1.0.0': i === 14999 ? { p0: '*' } : { [`p${i + 1}`]: '*' } };
    expected[`p${i}`] = '1.0.0';
  }
  assert.deepEqual(resolve(registry, { p0: '*' }), expected);
});

test('early conflicts prune choices before exploring unrelated Cartesian combinations', () => {
  const registry = {
    a: { '2.0.0': {}, '1.0.0': {} },
    b: { '2.0.0': { a: '1.0.0' }, '1.0.0': { a: '1.0.0' } },
  };
  const root = { a: '*', b: '*' };
  const expected = { a: '1.0.0', b: '2.0.0' };
  for (let i = 0; i < 32; i += 1) {
    registry[`p${i}`] = { '2.0.0': {}, '1.0.0': {} };
    root[`p${i}`] = '*';
    expected[`p${i}`] = '2.0.0';
  }
  assert.deepEqual(resolve(registry, root), expected);
});

test('only selected versions determine reachability; missing packages are unsatisfiable', () => {
  const registry = { a: { '2.0.0': {}, '1.0.0': { missing: '*' } } };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '2.0.0' });
  assert.equal(resolve(registry, { a: '1.0.0' }), null);
  assert.equal(resolve(registry, { missing: '*' }), null);
  assert.deepEqual(resolve(registry, {}), {});
});

test('all maps, versions and ranges are validated even when unreachable', () => {
  for (const registry of [
    null, [], new Date(), { unused: [] }, { unused: { bad: {} } },
    { unused: { '1.0.0': null } }, { unused: { '1.0.0': { x: '' } } },
    { unused: { '1.0.0\n': {} } },
