  const root = Object.create(null);
  const deps = Object.create(null);
  deps.constructor = '*';
  registry.__proto__ = { '1.0.0': Object.freeze(deps) };
  registry.constructor = { '1.0.0': Object.freeze({}) };
  Object.defineProperty(registry, 'ignored', { value: null });
  root.__proto__ = '*';
  Object.defineProperty(root, 'ignored', { value: 'invalid' });
  Object.freeze(registry.__proto__);
  Object.freeze(registry.constructor);
  Object.freeze(registry);
  Object.freeze(root);
  const result = resolve(registry, root);
  assert.deepEqual(result, JSON.parse('{"__proto__":"1.0.0","constructor":"1.0.0"}'));
  assert.equal(Object.getPrototypeOf(result), Object.prototype);
  assert.deepEqual(Object.keys(deps), ['constructor']);
});

test('versions are canonical safe integer triples with no suffix or whitespace', () => {
  assert.deepEqual(parse('9007199254740991.10.0'), [Number.MAX_SAFE_INTEGER, 10, 0]);
  for (const version of [
    '', '1.2', '01.2.3', '1.02.3', '1.2.03', '-1.2.3', '1.2.3-pre',
    '1.2.3+build', ' 1.2.3', '1.2.3 ', '1.2.3\n', '1.2.3\r',
    '1.2.3\u2028', '9007199254740992.0.0', null, 123,
