    b: { '2.0.0': { x: '1.0.0' }, '1.0.0': { x: '2.0.0' } },
    x: { '2.0.0': {}, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*', x: '*', b: '*' }), {
    a: '2.0.0', x: '2.0.0', b: '1.0.0',
  });
  assert.deepEqual(resolve(registry, { a: '*', b: '*' }), {
    a: '2.0.0', b: '2.0.0', x: '1.0.0',
  });
});

test('dependency key order determines the first solution rather than a global version maximum', () => {
  const registry = {
    a: { '1.0.0': { b: '*', c: '*' } },
    b: { '2.0.0': { c: '1.0.0' }, '1.0.0': {} },
    c: { '2.0.0': { b: '1.0.0' }, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '1.0.0', b: '2.0.0', c: '1.0.0' });
  registry.a['1.0.0'] = { c: '*', b: '*' };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '1.0.0', c: '2.0.0', b: '1.0.0' });
});

test('a discovered conflict retries the latest choice and removes partial dependencies', () => {
  const registry = {
    a: { '2.0.0': {}, '1.0.0': {} },
    b: { '2.0.0': { discarded: '*', a: '1.0.0' }, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*', b: '*' }), { a: '2.0.0', b: '1.0.0' });
});

test('rollback removes failed branch constraints, queued names and selections', () => {
  const registry = {
    a: { '2.0.0': { x: '1.0.0', missing: '*' }, '1.0.0': { x: '2.0.0' } },
    x: { '2.0.0': {}, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*', x: '*' }), { a: '1.0.0', x: '2.0.0' });
});

test('rollback preserves constraints from earlier choices', () => {
  const registry = {
    a: { '1.0.0': { x: '<2.0.0' } },
    b: { '2.0.0': { x: '2.0.0' }, '1.0.0': { x: '*' } },
    x: { '2.0.0': {}, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*', b: '*' }), {
    a: '1.0.0', b: '1.0.0', x: '1.0.0',
  });
});

test('cycles expand each selected package once and still enforce incoming constraints', () => {
  const registry = {
    a: { '2.0.0': { b: '*' }, '1.0.0': { a: '*', b: '*' } },
    b: { '1.0.0': { a: '1.0.0' } },
  };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
  assert.equal(resolve(registry, { a: '2.0.0' }), null);
});

test('a self-dependency can reject a choice without leaking its constraint into the retry', () => {
  const registry = {
    a: { '2.0.0': { a: '1.0.0' }, '1.0.0': { a: '*' } },
  };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '1.0.0' });
});

test('long chains resolve and backtrack without a call-stack or iteration limit', () => {
  const registry = {};
